'use strict';
window.API={csrfToken:'',requestKeys:new Map(),operations:new Map(),lastServerResponse:null,
 async fingerprint(path,method,body){const canonical=v=>v&&typeof v==='object'?(Array.isArray(v)?v.map(canonical):Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])]))):v??null;return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(method+path+JSON.stringify(canonical(body)))) )].map(x=>x.toString(16).padStart(2,'0')).join('');},
 saveReceipts(){try{const prior=JSON.parse(sessionStorage.getItem('musonoi-pending')||'[]').filter(r=>r.user_id!==window.CurrentUser?.id);sessionStorage.setItem('musonoi-pending',JSON.stringify([...prior,...[...this.operations.values()].filter(o=>o.state==='UNKNOWN'||o.state==='SUBMITTING').map(({key,path,method,user_id,at,fingerprint})=>({key,path,method,user_id,at,fingerprint}))]));}catch{}window.dispatchEvent(new Event('operation-state'));},
 restoreReceipts(){try{for(const r of JSON.parse(sessionStorage.getItem('musonoi-pending')||'[]'))if(r.user_id===window.CurrentUser?.id&&!this.operations.has(r.key))this.operations.set(r.key,{...r,state:'UNKNOWN'});}catch{}this.saveReceipts();},
 async check(key){const o=this.operations.get(key);if(!o||o.user_id!==window.CurrentUser?.id)throw Error('没有未确认操作');const r=await this.request('/operations/status?'+new URLSearchParams({key:o.key,path:o.path,method:o.method}));o.state=r.committed?'CONFIRMED':'UNKNOWN';if(r.committed)delete o.options;this.saveReceipts();return r;},
 async retry(key){const o=this.operations.get(key);if(!o?.options||o.user_id!==window.CurrentUser?.id)throw Error('请保留原幂等键；重新加载后请先查询结果，不自动重建写入');return this.request(o.path,{...o.options,idempotencyKey:key});},
 async request(url,options={}){const method=options.method||'GET',isBusiness=method!=='GET'&&/^\/(v262|v261|v26|stock-map|masters|contracts|receipts|plans|allocations|samples|weighings|loads|outbounds|moves|stocktakes|exceptions|exception-rules|adjustments|labels|me\/language)(\/|$)/.test(url),tracked=isBusiness&&!options.binary&&!/\/(import-preview|exports?|selection)$/.test(url);let key=options.idempotencyKey;
  if(isBusiness&&!key){const signature=await this.fingerprint(url,method,options.body);if(!this.requestKeys.has(signature)){const old=[...this.operations.values()].find(o=>o.user_id===window.CurrentUser?.id&&o.fingerprint===signature);this.requestKeys.set(signature,old?.key||crypto.randomUUID());}key=this.requestKeys.get(signature);}let op,previousState;
  if(tracked){op=this.operations.get(key)||{key,path:url.split('?')[0],method,user_id:window.CurrentUser?.id||null,at:new Date().toISOString()};previousState=op.state;op.fingerprint=await this.fingerprint(url,method,options.body);op.options={...options,method,idempotencyKey:key};op.state='SUBMITTING';this.operations.set(key,op);this.saveReceipts();}
  const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':this.csrfToken}:{}),...(key?{'Idempotency-Key':key}:{}),...options.headers},controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),options.timeoutMs||15000),abort=()=>controller.abort();options.signal?.addEventListener('abort',abort,{once:true});if(options.signal?.aborted)controller.abort();
  try{const response=await fetch('/api/v1'+url,{credentials:'same-origin',...options,method,headers,signal:controller.signal,body:options.body?JSON.stringify(options.body):undefined,cache:'no-store'});
   if(!response.ok){const result=await response.json().catch(()=>({}));if(response.status===403&&result.error?.includes('安全令牌无效')&&!options.csrfRetried){this.csrfToken=(await this.request('/auth/csrf',{method:'POST',body:{}})).csrfToken;return await this.request(url,{...options,idempotencyKey:key,csrfRetried:true});}if(response.status===401&&window.AppSignedIn)window.dispatchEvent(new Event('session-expired'));const e=Error(result.error||'服务请求失败，未使用模拟数据替代。');e.statusCode=response.status;throw e;}
   const result=options.binary?{blob:await response.blob(),count:response.headers.get('X-Export-Count')}:await response.json();window.I18n?.protectResponse?.(result);this.lastServerResponse=new Date().toISOString();window.dispatchEvent(new Event('server-response'));if(op){op.state='CONFIRMED';delete op.options;this.saveReceipts();}if(method!=='GET'&&isBusiness)window.dispatchEvent(new Event('inventory-changed'));if(url==='/auth/logout'){this.operations.clear();this.requestKeys.clear();/* Minimal unknown receipts remain partitioned by account for safe re-login recovery. */}return result;
  }catch(e){if((!e.statusCode||e.statusCode>=500)&&/^\/(inventory|dashboard|stock-map|bundles|scan\/resolve)/.test(url))window.dispatchEvent(new Event('stock-stale'));if(op){op.state=e.statusCode&&e.statusCode<500&&previousState!=='UNKNOWN'?'REJECTED':'UNKNOWN';this.saveReceipts();}if(!e.statusCode){const err=Error(tracked?'提交状态未知：请求超时或网络中断；请保留原幂等键，重新查询操作结果。':'请求超时或网络中断；未联网查询到实时库存，请重新查询。');err.uncertain=tracked;err.operationKey=key;throw err;}throw e;
  }finally{clearTimeout(timeout);options.signal?.removeEventListener('abort',abort);}
 }};
